def _prepublication_requires_infrastructure_coherence(
    changed_paths: Sequence[str],
) -> bool:
    return any(
        path in PREPUBLICATION_INFRASTRUCTURE_PATHS
        or any(
            path.startswith(prefix)
            for prefix in PREPUBLICATION_INFRASTRUCTURE_TEST_PREFIXES
        )
        for path in changed_paths
    )


def _prepublication_admission_tests(changed_paths: Sequence[str]) -> tuple[str, ...]:
    if _prepublication_requires_infrastructure_coherence(changed_paths):
        return (
            *ARCH132_R3N_ADMISSION_TESTS,
            *PREPUBLICATION_INFRASTRUCTURE_COHERENCE_TESTS,
        )
    return ARCH132_R3N_ADMISSION_TESTS


def resolve_ci_checkpoint(
    specs: Mapping[str, CheckpointSpec],
    branch: str,
    event_name: str,
) -> str | None:
    """Use exactly one registered active branch on push; otherwise fail broad."""
    if event_name != "push" or type(branch) is not str or not branch:
        return None
    if branch == "feature/test-suite-current-authority-historical-decoupling-current":
        name = ARCH134_READONLY_DIAGNOSTIC_NAME
        return name if name in specs and specs[name].execute is None else None
    matches = [spec.name for spec in specs.values() if spec.remote_branch == branch]
    if len(matches) != 1 or matches[0] not in (
        *CURRENT_ACTIVE_CI_CHECKPOINTS,
        ACTIVE_CI_CHECKPOINTS[0],
        ARCH134_READONLY_DIAGNOSTIC_NAME,
    ):
        return None
    return matches[0]


def resolve_ci_certification_profile(checkpoint: str | None) -> str | None:
    """Return the reviewed GitHub-owned certification profile for one checkpoint."""
    if checkpoint is None:
        return None
    profile = CI_CERTIFICATION_PROFILES.get(checkpoint)
    if profile is not None and profile not in CI_CERTIFICATION_PROFILE_VALUES:
        raise RuntimeError(f"Unsupported CI certification profile: {profile}")
    return profile


def _github_ci_metadata(endpoint: str) -> object:
    """Read GitHub Actions metadata; never emit authentication or API error text."""
    result = subprocess.run(
        ("gh", "api", "--hostname", "github.com", endpoint),
        capture_output=True,
        text=True,
        timeout=30,
        check=True,
    )
    if len(result.stdout) > 2_000_000:
        raise ValueError("GitHub metadata exceeds the bounded lookup")
    return json.loads(result.stdout)


def find_reusable_ci_certification(
    specs: Mapping[str, CheckpointSpec],
    *,
    head: str,
    tree: str,
    current_run_id: int,
    repository_id: int,
    lookup: Callable[[str], object],
) -> dict[str, object]:
    """Prove one exact feature gate, otherwise retain broad CI.

    A mapped active checkpoint may reuse its canonical profile evidence.  A
    registered active checkpoint without a canonical profile may reuse the
    exact active-plus-four-shard broad source-gate topology, and an unregistered
    feature branch may reuse the exact four-shard broad source-gate topology.
    Every other shape falls back to the normal broad run. The output remains
    named ``reuse_certification`` for workflow compatibility, but
    ``reuse_kind`` distinguishes the proofs.
    """
    fallback = {"reuse": False, "reason": "provenance_not_proven"}
    repository = SOURCE_REPOSITORY
    prefix = f"repos/{repository}"
    path = ".github/workflows/checkpoint-source-gates.yml"

    def require(condition: object) -> None:
        if not condition:
            raise ValueError("Incomplete integration provenance")

    def page(value: object, field: str) -> list[dict]:
        require(type(value) is dict)
        items = value[field]
        require(type(items) is list and all(type(item) is dict for item in items))
        require(type(value["total_count"]) is int)
        # More than one bounded page is deliberately ineligible, never truncated proof.
        require(value["total_count"] == len(items) <= 100)
        return items

    def same_repository(value: object) -> bool:
        return (
            type(value) is dict
            and value.get("full_name") == repository
            and type(value.get("id")) is int
            and value["id"] == repository_id
        )

    def completed_success(
        by_name: Mapping[str, dict],
        name: str,
        steps: tuple[str, ...],
        run_id: int,
        attempt: int,
    ) -> bool:
        job = by_name.get(name, {})
        if not (
            job.get("status") == "completed"
            and job.get("conclusion") == "success"
            and job.get("run_id") == run_id
            and job.get("run_attempt") == attempt
            and job.get("run_attempt") == 1
            and job.get("head_sha") == head
        ):
            return False
        step_list = job["steps"]
        require(type(step_list) is list)
        step_map = {step["name"]: step for step in step_list}
        require(len(step_map) == len(step_list))
        return all(
            step_map.get(step, {}).get("conclusion") == "success"
            and step_map[step].get("status") == "completed"
            for step in steps
        )

    try:
        require(type(head) is str and re.fullmatch("[0-9a-f]{40}", head))
        require(type(tree) is str and re.fullmatch("[0-9a-f]{40}", tree))
        require(type(current_run_id) is int and current_run_id > 0)
        require(type(repository_id) is int and repository_id > 0)
        require(same_repository(lookup(prefix)))
        workflow = lookup(f"{prefix}/actions/workflows/checkpoint-source-gates.yml")
        require(type(workflow) is dict)
        require(type(workflow["id"]) is int and workflow["id"] > 0)
        require(workflow["name"] == "Checkpoint Source Gates")
        require(workflow["path"] == path and workflow["state"] == "active")
        commit = lookup(f"{prefix}/git/commits/{head}")
        require(commit["sha"] == head and commit["tree"]["sha"] == tree)
        develop = lookup(f"{prefix}/git/ref/heads/develop")
        require(develop["ref"] == "refs/heads/develop")
        require(develop["object"]["type"] == "commit")
        require(develop["object"]["sha"] == head)
        runs = page(
            lookup(
                f"{prefix}/actions/workflows/{workflow['id']}/runs"
                f"?head_sha={head}&event=push&per_page=100"
            ),
            "workflow_runs",
        )
        candidates = []
        for run in runs:
            # Develop's own runs are never a source of feature certification.
            if run.get("id") == current_run_id or run.get("head_branch") == "develop":
                continue
            branch = run["head_branch"]
            require(type(branch) is str)
            if not branch.startswith(
                ("feature/robinhood-", "feature/research-", "feature/test-suite-")
            ):
                continue
            checkpoint = resolve_ci_checkpoint(specs, branch, "push")
            profile = resolve_ci_certification_profile(checkpoint)
            mapped = checkpoint is not None and profile is not None
            registered_broad = checkpoint is not None and profile is None
            unregistered_broad = checkpoint is None and profile is None
            if not mapped and not registered_broad and not unregistered_broad:
                continue
            if not (
                same_repository(run["repository"])
                and same_repository(run["head_repository"])
                and run["name"] == workflow["name"]
                and run["workflow_id"] == workflow["id"]
                and run["path"] == path
                and run["head_sha"] == head
                and run["event"] == "push"
                and run["status"] == "completed"
                and run["conclusion"] == "success"
            ):
                continue
            run_id, attempt = run["id"], run["run_attempt"]
            require(type(run_id) is int and 0 < run_id < current_run_id)
            # Only the original push-triggered attempt is reusable evidence.
            require(type(attempt) is int and attempt == 1)
            detail = lookup(f"{prefix}/actions/runs/{run_id}")
            for key in (
                "id",
                "run_attempt",
                "repository",
                "head_repository",
                "name",
                "workflow_id",
                "path",
                "head_sha",
                "head_branch",
                "event",
                "status",
                "conclusion",
            ):
                require(detail[key] == run[key])
            require(detail["run_attempt"] == 1)
            jobs = page(
                lookup(
                    f"{prefix}/actions/runs/{run_id}/attempts/{attempt}/jobs?per_page=100"
                ),
                "jobs",
            )
            by_name = {job["name"]: job for job in jobs}
            require(len(by_name) == len(jobs))
            if mapped:
                certification = f"certification-tests ({checkpoint} / {profile})"
                required = {
                    "source-static": (
                        "Resolve source gate route",
                        "Verify active checkpoint static authority",
                    ),
                    "active-tests": ("Verify active checkpoint tests",),
                    certification: (
                        "Run canonical certification profile",
                        "Enforce canonical certification hygiene budget",
                    ),
                    # The mapped route still materializes the reviewed
                    # full-tests job with a skipped conclusion.  It is part
                    # of the exact #738 topology and must be proven, rather
                    # than silently ignored.
                    "full-tests": (),
                    "source-gates": ("Require source gate success",),
                }
                require(set(by_name) == set(required))
                eligible = all(
                    completed_success(by_name, name, steps, run_id, attempt)
                    for name, steps in required.items()
                    if name != "full-tests"
                )
                skipped = by_name["full-tests"]
                eligible = eligible and (
                    skipped.get("status") == "completed"
                    and skipped.get("conclusion") == "skipped"
                    and skipped.get("run_id") == run_id
                    and skipped.get("run_attempt") == attempt
                    and skipped.get("head_sha") == head
                    and skipped.get("steps") == []
                )
            else:
                broad_jobs = {
                    "source-static": (
                        "Resolve source gate route",
                        "Prove exact develop certification reuse",
                        (
                            "Verify active checkpoint static authority"
                            if registered_broad
                            else "Verify full batch static authority"
                        ),
                    ),
                    "active-tests": (
                        ("Verify active checkpoint tests",) if registered_broad else ()
                    ),
                    **{
                        f"full-tests ({index})": (
                            "Record broad test shard start",
                            "Verify full batch test shard",
                            "Enforce broad test hygiene budget",
                        )
                        for index in range(4)
                    },
                    REVIEWED_SKIPPED_CERTIFICATION_JOB: (),
                    "source-gates": ("Require source gate success",),
                }
                require(set(by_name) == set(broad_jobs))
                eligible = all(
                    completed_success(by_name, name, steps, run_id, attempt)
                    for name, steps in broad_jobs.items()
                    if name != REVIEWED_SKIPPED_CERTIFICATION_JOB
                    and (registered_broad or name != "active-tests")
                )
                if registered_broad:
                    eligible = eligible and (
                        by_name["active-tests"].get("status") == "completed"
                        and by_name["active-tests"].get("conclusion") == "success"
                        and by_name["active-tests"].get("run_id") == run_id
                        and by_name["active-tests"].get("run_attempt") == attempt
                        and by_name["active-tests"].get("head_sha") == head
                    )
                else:
                    eligible = eligible and all(
                        by_name[name].get("status") == "completed"
                        and by_name[name].get("conclusion") == "skipped"
                        and by_name[name].get("run_id") == run_id
                        and by_name[name].get("run_attempt") == attempt
                        and by_name[name].get("head_sha") == head
                        for name in ("active-tests", REVIEWED_SKIPPED_CERTIFICATION_JOB)
                    )
                eligible = eligible and (
                    by_name[REVIEWED_SKIPPED_CERTIFICATION_JOB].get("status")
                    == "completed"
                    and by_name[REVIEWED_SKIPPED_CERTIFICATION_JOB].get("conclusion")
                    == "skipped"
                    and by_name[REVIEWED_SKIPPED_CERTIFICATION_JOB].get("run_id")
                    == run_id
                    and by_name[REVIEWED_SKIPPED_CERTIFICATION_JOB].get("run_attempt")
                    == attempt
                    and by_name[REVIEWED_SKIPPED_CERTIFICATION_JOB].get("head_sha")
                    == head
                )
            if eligible:
                evidence = {
                    "reuse": True,
                    "reason": (
                        "exact_feature_certification"
                        if mapped
                        else "exact_feature_broad_source_gate"
                    ),
                    "reuse_kind": (
                        "mapped_certification" if mapped else "broad_source_gate"
                    ),
                    "repository": repository,
                    "repository_id": repository_id,
                    "head": head,
                    "tree": tree,
                    "workflow_id": workflow["id"],
                    "run_id": run_id,
                    "run_attempt": attempt,
                    "branch": branch,
                    "checkpoint": checkpoint,
                    "profile": profile or "",
                    "run": detail,
                    "jobs": jobs,
                }
                if registered_broad:
                    evidence["route"] = "ACTIVE"
                elif unregistered_broad:
                    evidence["shards"] = [0, 1, 2, 3]
                    evidence["route"] = "FULL"
                candidates.append(evidence)
        if len(candidates) != 1:
            return {"reuse": False, "reason": "no_unique_certification"}
        return candidates[0]
    except Exception:
        # API, parsing and incomplete-evidence failures can only request more tests.
        return fallback


def resolve_develop_ci_reuse(repo_root: Path, mode: str) -> dict[str, object]:
    """Admit develop's current push context before considering optional reuse."""
    fallback = {"reuse": False, "reason": "not_eligible_develop_push"}
    repository = SOURCE_REPOSITORY
    if not (
        mode == "FULL"
        and os.environ.get("GITHUB_EVENT_NAME") == "push"
        and os.environ.get("GITHUB_REF") == "refs/heads/develop"
        and os.environ.get("GITHUB_REF_NAME") == "develop"
        and os.environ.get("GITHUB_REPOSITORY") == repository
        and os.environ.get("GITHUB_SERVER_URL") == "https://github.com"
        and os.environ.get("GITHUB_WORKFLOW") == "Checkpoint Source Gates"
        and os.environ.get("GITHUB_WORKFLOW_REF")
        == (
            f"{repository}/.github/workflows/checkpoint-source-gates.yml"
            "@refs/heads/develop"
        )
    ):
        return fallback
    try:
        before = _git_state(repo_root)
        head = before["head"]
        if (
            before["porcelain"]
            or before["branch"] != "develop"
            or head != os.environ.get("GITHUB_SHA")
            or _git_output(repo_root, "remote", "get-url", "origin")
            != f"https://github.com/{repository}"
            and _git_output(repo_root, "remote", "get-url", "origin")
            != f"https://github.com/{repository}.git"
        ):
            return fallback
        event = json.loads(Path(os.environ["GITHUB_EVENT_PATH"]).read_text("utf-8"))
        base = event["before"]
        if not (
            event["ref"] == "refs/heads/develop"
            and event["after"] == head
            and event["forced"] is False
            and event["deleted"] is False
            and type(base) is str
            and re.fullmatch("[0-9a-f]{40}", base)
            and base != "0" * 40
        ):
            return fallback
        _git_output(repo_root, "merge-base", "--is-ancestor", base, str(head))
        result = find_reusable_ci_certification(
            _checkpoint_specs(),
            head=str(head),
            tree=str(before["tree"]),
            current_run_id=int(os.environ["GITHUB_RUN_ID"]),
            repository_id=int(os.environ["GITHUB_REPOSITORY_ID"]),
            lookup=_github_ci_metadata,
        )
        if _git_state(repo_root) != before:
            return {"reuse": False, "reason": "integration_source_changed"}
        return result
    except Exception:
        return {"reuse": False, "reason": "integration_provenance_unavailable"}


def _batch_workflow_is_reviewed(workflow: str) -> bool:
    # Freeze active routing, CI-owned certification, broad fallback and aggregation.
    # The frozen D1R5 fallback stays unchanged; D1R6/D1R7/D1R8/F1 route dynamically.
    workflow_active = tuple(
        name
        for name in ACTIVE_CI_CHECKPOINTS
        if name
        not in {
            ARCH134_D1R6_NAME,
            ARCH134_D1R7_NAME,
            ARCH134_D1R8_NAME,
            ARCH134_F1_NAME,
            ARCH144C_NAME,
        }
    )
    checkpoint_block = (
        "  AI_TRADING_BOT_ACTIVE_CHECKPOINTS: >-\n"
        + "".join(f"              {name} `\n" for name in workflow_active[:-1])
        + f"              {workflow_active[-1]}\n"
    )
    local_active = 'verify "${{ steps.route.outputs.checkpoint }}"'
    needs_active = 'verify "${{ needs.source-static.outputs.checkpoint }}"'
    batch = "verify-batch @Checkpoints"
    active_job = workflow.partition("  active-tests:\n")[2].partition(
        "\n  full-tests:\n"
    )[0]
    full_job = workflow.partition("  full-tests:\n")[2].partition(
        "\n  certification-tests:\n"
    )[0]
    certification_job = workflow.partition("  certification-tests:\n")[2].partition(
        "\n  source-gates:\n"
    )[0]
    aggregate_job = workflow.partition("  source-gates:\n")[2]

    active_header = (
        "    needs: source-static\n"
        "    if: needs.source-static.outputs.mode != 'DOCS_ONLY' && "
        "needs.source-static.outputs.route == 'ACTIVE'\n"
        "    runs-on: windows-latest\n"
        "    timeout-minutes: 20\n"
    )
    full_header = (
        "    needs: source-static\n"
        "    if: needs.source-static.outputs.mode != 'DOCS_ONLY' && "
        "needs.source-static.outputs.certification_profile == '' && "
        "needs.source-static.outputs.reuse_certification != 'true'\n"
        "    runs-on: windows-latest\n"
        "    timeout-minutes: 20\n"
        "    strategy:\n"
        "      fail-fast: false\n"
        "      matrix:\n"
        "        shard: [0, 1, 2, 3]\n"
    )
    certification_header = (
        "    name: certification-tests "
        "(${{ needs.source-static.outputs.checkpoint }} / "
        "${{ needs.source-static.outputs.certification_profile }})\n"
        "    needs: source-static\n"
        "    if: needs.source-static.outputs.mode != 'DOCS_ONLY' && "
        "needs.source-static.outputs.certification_profile != ''\n"
        "    runs-on: windows-latest\n"
        "    timeout-minutes: 20\n"
    )
    broad_start = (
        "      - name: Record broad test shard start\n"
        "        shell: powershell\n"
        "        run: |\n"
        "          $Started = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()\n"
        '          "AI_TRADING_BOT_BROAD_SHARD_STARTED_MS=$Started" |\n'
        "            Out-File -FilePath $env:GITHUB_ENV -Encoding utf8 -Append\n"
        "\n"
    )
    broad_execution = (
        "      - name: Verify full batch test shard\n"
        "        env:\n"
        "          AI_TRADING_BOT_SOURCE_GATE_PHASE: tests\n"
        "          AI_TRADING_BOT_SOURCE_GATE_SHARD_INDEX: ${{ matrix.shard }}\n"
        "          AI_TRADING_BOT_SOURCE_GATE_SHARD_COUNT: 4\n"
        "          AI_TRADING_BOT_CHECKPOINT_EVIDENCE_ROOT: ${{ "
        "runner.temp }}/ai-trading-bot-checkpoints\n"
        "        shell: powershell\n"
        "        run: |\n"
        "          $Checkpoints = @(\n"
        "            $env:AI_TRADING_BOT_ACTIVE_CHECKPOINTS -split '\\s+' |\n"
        "              Where-Object { $_ -like 'arch*' }\n"
        "          )\n"
        "          & powershell.exe -NoProfile -ExecutionPolicy "
        "Bypass -File .\\ops.ps1 verify-batch @Checkpoints\n"
        "          exit $LASTEXITCODE\n"
        "\n"
    )
    broad_hygiene = (
        "      - name: Enforce broad test hygiene budget\n"
        "        if: always()\n"
        "        shell: powershell\n"
        "        run: |\n"
        "          $Started = [int64]$env:AI_TRADING_BOT_BROAD_SHARD_STARTED_MS\n"
        "          $Finished = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()\n"
        "          $Seconds = [math]::Round(($Finished - $Started) / 1000.0, 3)\n"
        '          Write-Host "BROAD_TEST_SHARD_SECONDS=$Seconds"\n'
        "          if ($Seconds -ge 300) {\n"
        '            Write-Host "::error::Broad test shard exceeded '
        "the 300-second hygiene threshold ($Seconds s). Run a test "
        'topology/hygiene audit before accepting this source."\n'
        "            exit 86\n"
        "          }\n"
        "\n"
    )
    certification_run_marker = (
        "      - name: Run canonical certification profile\n"
        "        env:\n"
        "          CERT_PROFILE: "
        "${{ needs.source-static.outputs.certification_profile }}\n"
    )
    certification_hygiene_marker = (
        "      - name: Enforce canonical certification hygiene budget\n"
        "        if: always()\n"
    )
    aggregate_policy = (
        "    needs: [source-static, active-tests, full-tests, "
        "certification-tests]\n"
        "    if: always()\n"
        "    runs-on: ubuntu-latest\n"
        "    timeout-minutes: 5\n"
        "\n"
        "    steps:\n"
        "      - name: Require source gate success\n"
        "        shell: bash\n"
        "        env:\n"
        "          STATIC_RESULT: ${{ needs.source-static.result }}\n"
        "          ACTIVE_RESULT: ${{ needs.active-tests.result }}\n"
        "          FULL_RESULT: ${{ needs.full-tests.result }}\n"
        "          CERT_RESULT: ${{ needs.certification-tests.result }}\n"
        "          REUSE: ${{ needs.source-static.outputs.reuse_certification }}\n"
        "          EVENT: ${{ github.event_name }}\n"
        "          REF: ${{ github.ref }}\n"
        "          MODE: ${{ needs.source-static.outputs.mode }}\n"
        "          ROUTE: ${{ needs.source-static.outputs.route }}\n"
        "          CERT_PROFILE: "
        "${{ needs.source-static.outputs.certification_profile }}\n"
        "        run: |\n"
        "          set -euo pipefail\n"
        '          test "$STATIC_RESULT" = "success"\n'
        "\n"
        '          if [ "$MODE" = "DOCS_ONLY" ]; then\n'
        '            test "$ACTIVE_RESULT" = "skipped"\n'
        '            test "$FULL_RESULT" = "skipped"\n'
        '            test "$CERT_RESULT" = "skipped"\n'
        '          elif [ "$REUSE" = "true" ]; then\n'
        '            test "$EVENT" = "push"\n'
        '            test "$REF" = "refs/heads/develop"\n'
        '            test "$ROUTE" = "FULL"\n'
        '            test -z "$CERT_PROFILE"\n'
        '            test "$ACTIVE_RESULT" = "skipped"\n'
        '            test "$FULL_RESULT" = "skipped"\n'
        '            test "$CERT_RESULT" = "skipped"\n'
        '          elif [ "$ROUTE" = "ACTIVE" ] && [ -n "$CERT_PROFILE" ]; then\n'
        '            test "$ACTIVE_RESULT" = "success"\n'
        '            test "$FULL_RESULT" = "skipped"\n'
        '            test "$CERT_RESULT" = "success"\n'
        '          elif [ "$ROUTE" = "ACTIVE" ]; then\n'
        '            test "$ACTIVE_RESULT" = "success"\n'
        '            test "$FULL_RESULT" = "success"\n'
        '            test "$CERT_RESULT" = "skipped"\n'
        "          else\n"
        '            test "$ACTIVE_RESULT" = "skipped"\n'
        '            test "$FULL_RESULT" = "success"\n'
        '            test "$CERT_RESULT" = "skipped"\n'
        "          fi\n"
    )
    return (
        workflow.count("      - name: Prove exact develop certification reuse\n") == 1
        and hashlib.sha256(
            workflow.partition(
                "      - name: Prove exact develop certification reuse\n"
            )[2]
            .partition("      - name: Validate docs-only range\n")[0]
            .encode()
        ).hexdigest()
        == "0cf6a2b45d90f88d472912805e742a2744508a8c832039a804ac28ea506ab744"
        and (
            "      reuse_certification: "
            "${{ steps.reuse.outputs.reuse_certification }}\n"
        )
        in workflow
        and (
            "  source-static:\n    permissions:\n"
            "      contents: read\n      actions: read\n"
        )
        in workflow
        and active_job.startswith(active_header + "\n    steps:\n")
        and full_job.startswith(full_header + "\n    steps:\n")
        and certification_job.startswith(certification_header + "\n    steps:\n")
        and workflow.count("  active-tests:\n") == 1
        and workflow.count("  full-tests:\n") == 1
        and workflow.count("  certification-tests:\n") == 1
        and aggregate_job == aggregate_policy
        and full_job.count(broad_start) == 1
        and full_job.count(broad_hygiene) == 1
        and full_job.count(broad_execution) == 1
        and full_job.count("      - name: Upload full test evidence\n") == 1
        and full_job.index(broad_start)
        < full_job.index(broad_execution)
        < full_job.index(broad_hygiene)
        < full_job.index("      - name: Upload full test evidence\n")
        and certification_job.count(certification_run_marker) == 1
        and certification_job.count(certification_hygiene_marker) == 1
        and certification_job.count(
            ".\\scripts\\run_test_certification.py `\n"
            "              --profile $env:CERT_PROFILE"
        )
        == 1
        and certification_job.count(
            'Write-Host "CANONICAL_CERTIFICATION_WALL_SECONDS=$Wall"'
        )
        == 1
        and certification_job.count("if ($Wall -ge 300)") == 1
        and certification_job.count("exit 86") == 1
        and certification_job.count(
            "      - name: Upload canonical certification evidence\n"
        )
        == 1
        and workflow.count(checkpoint_block) == 1
        and workflow.count(batch) == 2
        and workflow.count(batch + "\n          exit $LASTEXITCODE") == 2
        and workflow.count(local_active) == 1
        and workflow.count(local_active + "\n          exit $LASTEXITCODE") == 1
        and workflow.count(needs_active) == 1
        and workflow.count(needs_active + "\n          exit $LASTEXITCODE") == 1
        and workflow.count("AI_TRADING_BOT_SOURCE_GATE_PHASE: static") == 2
        and workflow.count("AI_TRADING_BOT_SOURCE_GATE_PHASE: tests") == 2
        and "resolve_ci_checkpoint(" in workflow
        and "resolve_ci_certification_profile(" in workflow
        and "shard: [0, 1, 2, 3]" in workflow
        and "group: ${{ github.workflow }}-${{ github.ref }}" in workflow
        and "cancel-in-progress: true" in workflow
        and "workflow_dispatch:" in workflow
        and workflow.count(
            "  source-gates:\n"
            "    needs: [source-static, active-tests, full-tests, "
            "certification-tests]\n"
            "    if: always()\n"
        )
        == 1
        and workflow.count("  source-static:\n") == 1
        and workflow.count("- name: Require source gate success") == 1
        and "verify arch" not in workflow
    )


def _git_blob_sha1(path: Path) -> str:
    # Text mode normalizes Git's LF source across Windows checkout CRLF.
    data = path.read_text(encoding="utf-8").encode("utf-8")
    return hashlib.sha1(
        b"blob " + str(len(data)).encode("ascii") + bytes((0,)) + data
    ).hexdigest()


def _qualified_names(node: ast.AST) -> set[str]:
    result: set[str] = set()
    for item in ast.walk(node):
        if isinstance(item, ast.Name):
            result.add(item.id)
        elif isinstance(item, ast.Attribute):
            parts: list[str] = []
            current: ast.AST = item
            while isinstance(current, ast.Attribute):
                parts.append(current.attr)
                current = current.value
            if isinstance(current, ast.Name):
                parts.append(current.id)
                result.add(".".join(reversed(parts)))
    return result


def _top_level_functions(tree: ast.Module) -> dict[str, ast.FunctionDef]:
    return {node.name: node for node in tree.body if isinstance(node, ast.FunctionDef)}


def _r4_authority_check(repo_root: Path) -> tuple[str, ...]:
    path = repo_root / "scripts" / "d10_arch128_r4_operator.py"
    source = path.read_text(encoding="utf-8")
    tree = ast.parse(source, filename=str(path))
    functions = _top_level_functions(tree)
    failures: list[str] = []

    required_functions = {
        "_read_only_preflight",
        "_execute_once",
        "_dispatch",
        "main",
    }
    missing_functions = sorted(required_functions - set(functions))
    if missing_functions:
        failures.append(f"missing functions: {missing_functions}")
        return tuple(failures)

    readonly_names = _qualified_names(functions["_read_only_preflight"])
    forbidden_readonly = {
        "r4w.WindowsArch128StagingBackend",
        "r4w.rename_fixed_step",
        "r4c._construct_staging",
        "r4c._ReplacementSession",
    }
    bad_readonly = sorted(forbidden_readonly & readonly_names)
    if bad_readonly:
        failures.append(
            f"read-only mode references protected mutation symbols: {bad_readonly}"
        )

    execute_names = _qualified_names(functions["_execute_once"])
    required_execute = {
        "r4w.WindowsArch128StagingBackend",
        "r4w.WindowsArch128ReadOnlyReader",
        "r4c._construct_staging",
        "r4c._ReplacementSession",
        "r4w.rename_fixed_step",
    }
    missing_execute = sorted(required_execute - execute_names)
    if missing_execute:
        failures.append(f"protected mode missing fixed bindings: {missing_execute}")

    dispatch_source = ast.get_source_segment(source, functions["_dispatch"]) or ""
    for required in ("READ_ONLY_FLAG", "EXECUTE_FLAG", "AUTH_ENV", "AUTH_VALUE"):
        if required not in dispatch_source:
            failures.append(f"dispatch interlock missing: {required}")

    for forbidden in (
        "RegisterTask",
        "RegisterTaskDefinition",
        "DeleteTask",
        "Start-ScheduledTask",
        "Enable-ScheduledTask",
        "WindowsActivationLeaseBackend",
        "publish_activation",
        "rmtree",
        "unlink(",
        "os.rename",
    ):
        if forbidden in source:
            failures.append(
                f"operator contains forbidden authority surface: {forbidden}"
            )

    runner_path = repo_root / "scripts" / "checkpoint_runner.py"
    runner_source = runner_path.read_text(encoding="utf-8")
    runner_tree = ast.parse(runner_source, filename=str(runner_path))
    runner_functions = _top_level_functions(runner_tree)
    r4_execute = runner_functions.get("_r4_execute")
    if r4_execute is None:
        failures.append("runner missing _r4_execute")
    else:
        execute_names = _qualified_names(r4_execute)
        for required in (
            "operator._dispatch",
            "operator.EXECUTE_FLAG",
            "os.environ",
        ):
            if required not in execute_names:
                failures.append(
                    f"runner R4 execute missing reviewed dispatch binding: {required}"
                )
        for forbidden in (
            "operator._execute_once",
            "r4c._construct_staging",
            "r4c._ReplacementSession",
            "r4w.WindowsArch128StagingBackend",
            "r4w.rename_fixed_step",
        ):
            if forbidden in execute_names:
                failures.append(
                    f"runner R4 execute bypasses reviewed interlock: {forbidden}"
                )

    return tuple(failures)


def _r5_authority_check(repo_root: Path) -> tuple[str, ...]:
    child_path = repo_root / "scripts" / "d10_arch128_r5_trading_child.py"
    child_source = child_path.read_text(encoding="utf-8")
    child_tree = ast.parse(child_source, filename=str(child_path))
    child_functions = _top_level_functions(child_tree)
    failures: list[str] = []

    qualify = child_functions.get("_qualify")
    if qualify is None:
        failures.append("R5 Trading child missing _qualify")
    else:
        names = _qualified_names(qualify)
        for required in (
            "guard_module._verify_pre_source",
            "guard_module._Native",
            "guard_module._require_facts",
            "guard_module._stable",
            "backend.require_absent",
            "backend.listdir",
        ):
            if required not in names:
                failures.append(
                    f"R5 Trading child missing read-only binding: {required}"
                )
        for forbidden in (
            "guard_module.main",
            "guard_module._run_second_stage_with_evidence",
            "backend.append_exact",
            "backend.open_evidence_file",
        ):
            if forbidden in names:
                failures.append(
                    f"R5 Trading child references effect binding: {forbidden}"
                )

    for forbidden in (
        "RegisterTask",
        "RegisterTaskDefinition",
        "Start-ScheduledTask",
        "Enable-ScheduledTask",
        "WindowsActivationLeaseBackend",
        "publish_activation",
        "WriteFile",
        "MoveFile",
        "os.rename",
        "unlink(",
        "rmtree",
    ):
        if forbidden in child_source:
            failures.append(f"R5 Trading child contains forbidden surface: {forbidden}")

    runner_path = repo_root / "scripts" / "checkpoint_runner.py"
    runner_source = runner_path.read_text(encoding="utf-8")
    runner_tree = ast.parse(runner_source, filename=str(runner_path))
    runner_functions = _top_level_functions(runner_tree)
    substrate = runner_functions.get("_r5_substrate_preflight")
    trading = runner_functions.get("_r5_trading_preflight")
    if substrate is None:
        failures.append("runner missing _r5_substrate_preflight")
    else:
        names = _qualified_names(substrate)
        for required in ("h.collect", "w.WindowsCollector", "os.environ"):
            if required not in names:
                failures.append(f"R5 substrate runner missing binding: {required}")
    if trading is None:
        failures.append("runner missing _r5_trading_preflight")
    else:
        names = _qualified_names(trading)
        for required in ("subprocess.run", "json.loads"):
            if required not in names:
                failures.append(f"R5 Trading runner missing binding: {required}")

    return tuple(failures)


def _r6_authority_check(repo_root: Path) -> tuple[str, ...]:
    path = repo_root / "scripts" / "d10_arch128_r6_reactivation.py"
    source = path.read_text(encoding="utf-8")
    tree = ast.parse(source, filename=str(path))
    functions = _top_level_functions(tree)
    failures: list[str] = []

    for required in (
        "derive_reactivation_plan",
        "_require_evidence",
        "_require_trading_probe",
        "_require_admission",
    ):
        if required not in functions:
            failures.append(f"R6 source missing required function: {required}")

    forbidden = (
        "subprocess",
        "ctypes",
        "Start-ScheduledTask",
        "RegisterTask",
        "RegisterTaskDefinition",
        "WindowsActivationLeaseBackend",
        "WindowsDeploymentBackend",
        "CreateFileW",
        "MoveFile",
        "os.remove",
        "os.unlink",
        "shutil.rmtree",
    )
    for token in forbidden:
        if token in source:
            failures.append(f"R6 source contains protected host surface: {token}")

    if "execute_r7: bool = False" not in source:
        failures.append("R6 execution interlock is not explicit")
    if '"manual_task_start": "NOT_RUN"' not in source:
        failures.append("R6 source does not freeze manual task start closed")
    if "LEASE_PUBLICATION_STEPS" not in source:
        failures.append("R6 source does not bind tmp/installing/final publication")

    return tuple(failures)


