def _arch145a_predecessor_active_checkpoint_inventory() -> tuple[str, ...]:
    predecessor = ARCH145A_PREDECESSOR_ACTIVE_CI_CHECKPOINTS
    if ARCH134_D1S3_ACTIVE_CI_CHECKPOINTS_SHA256:
        successor = _arch134_r5_active_inventory(
            (ARCH134_D1S3_NAME, *ARCH134_D1S2_SUCCESSOR_ACTIVE_CI_CHECKPOINTS)
        )
        if (
            _arch146a_predecessor_active_inventory() != successor
            or _arch146a_predecessor_active_digest() != ARCH134_FRESH_ACTIVE_SHA256
        ):
            raise ValueError("D1S3 active checkpoint successor overlay drift")
        return successor
    if (
        type(predecessor) is not tuple
        or hashlib.sha256(
            ast.dump(
                ast.parse(repr(predecessor), mode="eval").body,
                include_attributes=False,
            ).encode("utf-8")
        ).hexdigest()
        != ARCH145A_PREDECESSOR_ACTIVE_CI_CHECKPOINTS_SHA256
        or predecessor != ARCH134_F1R1_B_PREDECESSOR_ACTIVE_CI_CHECKPOINTS
        or hashlib.sha256(
            ast.dump(
                ast.parse(
                    repr(ARCH134_F1R1_B_SUCCESSOR_ACTIVE_CI_CHECKPOINTS),
                    mode="eval",
                ).body,
                include_attributes=False,
            ).encode("utf-8")
        ).hexdigest()
        != ARCH134_F1R1_B_SUCCESSOR_ACTIVE_CI_CHECKPOINTS_SHA256
        or _arch146a_predecessor_active_inventory()
        != ARCH134_D1S2_SUCCESSOR_ACTIVE_CI_CHECKPOINTS
        or _arch146a_predecessor_active_digest()
        != (
            ARCH134_R5_ACTIVE_CI_CHECKPOINTS_SHA256
            if ARCH134_D1S3_ACTIVE_CI_CHECKPOINTS_SHA256
            else ARCH134_D1S2_SUCCESSOR_ACTIVE_CI_CHECKPOINTS_SHA256
        )
    ):
        raise ValueError("145-A active checkpoint successor overlay drift")
