def _arch134_d1s2_current_source_pin(relative: str, predecessor: str) -> str:
    before, after = ARCH134_D1S2_PREDECESSOR_PINS, ARCH134_D1S2_SUCCESSOR_PINS
    if (
        set(before) != set(ARCH134_D1S2_SHARED_PATHS)
        or hashlib.sha256(json.dumps(before, sort_keys=True).encode()).hexdigest()
        != ARCH134_D1S2_PREDECESSOR_PINS_SHA256
    ):
        raise ValueError("D1S2 shared successor overlay drift")
    if relative not in before or predecessor != before[relative]:
        raise ValueError("D1S2 wrong shared predecessor blob")
    if after is None:
        return predecessor
    if (
        set(after) != set(before)
        or hashlib.sha256(json.dumps(after, sort_keys=True).encode()).hexdigest()
        != ARCH134_D1S2_SUCCESSOR_PINS_SHA256
    ):
        raise ValueError("D1S2 shared successor overlay drift")
    successor_pin = _arch134_d1s3_shared_successor_pin(relative)
    if successor_pin is not None:
        return successor_pin
    return after[relative]


def _arch134_d1s2_source_pin(relative: str, predecessor: str) -> str:
    before, after = (
        ARCH134_D1S2_SOURCE_PREDECESSOR_PINS,
        ARCH134_D1S2_SOURCE_PINS,
    )
    if (
        type(before) is not dict
        or hashlib.sha256(json.dumps(before, sort_keys=True).encode()).hexdigest()
        != ARCH134_D1S2_SOURCE_PREDECESSOR_PINS_SHA256
    ):
        raise ValueError("D1S2 source overlay drift")
    if relative not in before:
        return predecessor
    if predecessor != before[relative]:
        raise ValueError("D1S2 wrong source predecessor blob")
    if after is None:
        return predecessor
    if type(after) is not dict or relative not in after:
        raise ValueError("D1S2 source overlay drift")
    successor_pin = _arch134_d1s3_shared_successor_pin(relative)
    if successor_pin is not None:
        return successor_pin
    return after[relative]


def _arch134_d1s2_runner_ast_pin(name: str, predecessor: str) -> str:
    before, after = (
        ARCH134_D1S2_PREDECESSOR_AST_PINS,
        ARCH134_D1S2_SUCCESSOR_AST_PINS,
    )
    if (
        set(before) != set(after)
        or hashlib.sha256(json.dumps(before, sort_keys=True).encode()).hexdigest()
        != ARCH134_D1S2_PREDECESSOR_AST_PINS_SHA256
        or hashlib.sha256(json.dumps(after, sort_keys=True).encode()).hexdigest()
        != ARCH134_D1S2_SUCCESSOR_AST_PINS_SHA256
    ):
        raise ValueError("D1S2 runner AST overlay drift")
    if name not in before or predecessor != before[name]:
        raise ValueError("D1S2 wrong runner AST predecessor")
    return after[name]


def _arch134_d1s2_active_inventory() -> tuple[str, ...]:
    before = ARCH134_D1S1_SUCCESSOR_ACTIVE_CI_CHECKPOINTS
    after = ARCH134_D1S2_SUCCESSOR_ACTIVE_CI_CHECKPOINTS

    if ARCH134_D1S3_ACTIVE_CI_CHECKPOINTS_SHA256:
        successor = _arch134_r5_active_inventory((ARCH134_D1S3_NAME, *after))
        if (
            _arch146a_predecessor_active_inventory() != successor
            or _arch146a_predecessor_active_digest() != ARCH134_FRESH_ACTIVE_SHA256
        ):
            raise ValueError("D1S3 exact active inventory drift")
        return successor

    def digest_tuple(value):
        return hashlib.sha256(
            ast.dump(
                ast.parse(repr(value), mode="eval").body, include_attributes=False
            ).encode()
        ).hexdigest()

    expected = (
        before[: before.index(ARCH134_D1S1_NAME)]
        + (ARCH134_D1S2_NAME,)
        + before[before.index(ARCH134_D1S1_NAME) :]
    )
    if (
        digest_tuple(before) != ARCH134_D1S1_SUCCESSOR_ACTIVE_CI_CHECKPOINTS_SHA256
        or after != expected
        or _arch146a_predecessor_active_inventory() != after
        or digest_tuple(after) != ARCH134_D1S2_SUCCESSOR_ACTIVE_CI_CHECKPOINTS_SHA256
        or _arch146a_predecessor_active_digest() != digest_tuple(after)
    ):
        raise ValueError("D1S2 exact active inventory drift")
    return after


def _arch134_d1s2_authority_check(repo_root: Path) -> tuple[str, ...]:
    failures = []
    try:
        _arch134_d1s2_active_inventory()
        if (
            type(ARCH134_D1S2_SOURCE_PINS) is not dict
            or hashlib.sha256(
                json.dumps(ARCH134_D1S2_SOURCE_PINS, sort_keys=True).encode()
            ).hexdigest()
            != ARCH134_D1S3_D1S2_SOURCE_PINS_SHA256
        ):
            raise ValueError("D1S2 accepted own-source map drift")
        if (
            any(
                ARCH134_D1S2_PREDECESSOR_PINS[path] != ARCH134_D1S1_SUCCESSOR_PINS[path]
                for path in ARCH134_D1S1_SHARED_PATHS
            )
            or ARCH134_D1S2_PREDECESSOR_PINS[
                "tests/runtime/test_personal_desktop_d10_launch_guard.py"
            ]
            != "cf18ed76f6dc5881cab1442a0744f3ad162e87e0"
        ):
            failures.append("D1S2 predecessor is not the accepted D1S1 successor")
        if (
            ARCH134_D1S2_SOURCE_PREDECESSOR_PINS[
                "tests/review_paper/test_arch134_f1r1_d1s1_successor_soak.py"
            ]
            != ARCH134_D1S1_SOURCE_PINS[
                "tests/review_paper/test_arch134_f1r1_d1s1_successor_soak.py"
            ]
        ):
            failures.append("D1S2 source predecessor drift")
        for relative, pin in ARCH134_D1S2_SOURCE_PINS.items():
            if _arch134_d1s3_mutable_current_doc(relative):
                continue
            predecessor = ARCH134_D1S2_SOURCE_PREDECESSOR_PINS.get(relative)
            expected = (
                _arch134_d1s2_source_pin(relative, predecessor)
                if predecessor is not None
                else (_arch134_d1s3_shared_successor_pin(relative) or pin)
            )
            if not _authority_blob_matches(repo_root, repo_root / relative, expected):
                failures.append("D1S2 source drift: " + relative)
        for relative, pin in ARCH134_D1S2_PREDECESSOR_PINS.items():
            if _arch134_d1s3_mutable_current_doc(relative):
                continue
            if not _authority_blob_matches(
                repo_root,
                repo_root / relative,
                _arch134_d1s2_current_source_pin(relative, pin),
            ):
                failures.append("D1S2 shared successor drift: " + relative)
        old_test = "tests/review_paper/test_arch134_f1r1_d1s1_successor_soak.py"
        if not _authority_blob_matches(
            repo_root,
            repo_root / old_test,
            _arch134_d1s2_source_pin(
                old_test, ARCH134_D1S2_SOURCE_PREDECESSOR_PINS[old_test]
            ),
        ):
            failures.append("D1S2 D1S1 test overlay drift")
        tree = _authority_runner_tree(repo_root)
        functions = _top_level_functions(tree)
        for name, expected in ARCH134_D1S2_RUNNER_AST_PINS.items():
            expected = ARCH134_D1S3_RUNNER_AST_PINS.get(name, expected)
            if not _authority_ast_matches(
                repo_root, name, functions[name], _arch134_r5_ast_pin(name, expected)
            ):
                failures.append("D1S2 runner AST drift: " + name)
        for name, expected in ARCH134_D1S2_NEW_RUNNER_AST_PINS.items():
            expected = ARCH134_D1S3_RUNNER_AST_PINS.get(name, expected)
            if not _authority_ast_matches(
                repo_root, name, functions[name], _arch134_r5_ast_pin(name, expected)
            ):
                failures.append("D1S2 new runner AST drift: " + name)
        spec = _checkpoint_specs()[ARCH134_D1S2_NAME]
        if (
            spec.preflight is not None
            or spec.execute is not None
            or spec.remote_head_env is not None
            or spec.remote_branch != ARCH134_D1S2_BRANCH
            or spec.tests != ARCH134_D1S2_TESTS
            or spec.ruff_paths != ARCH134_D1S2_RUFF_PATHS
            or spec.authority_check is not _arch134_d1s2_authority_check
            or CI_CERTIFICATION_PROFILES.get(spec.name) != "robinhood"
            or not _batch_workflow_is_reviewed(
                (repo_root / ".github/workflows/checkpoint-source-gates.yml").read_text(
                    encoding="utf-8"
                )
            )
        ):
            failures.append("D1S2 source-only registration drift")
    except (OSError, ValueError, TypeError, KeyError, SyntaxError):
        failures.append("D1S2 authority unavailable")
    return tuple(failures)


def _arch134_d1s3_preflight() -> dict[str, object]:
    from trading_bot.supervised_release import successor_installation_operator

    return successor_installation_operator._preflight()


def _arch134_d1s3_execute() -> dict[str, object]:
    from trading_bot.supervised_release import successor_installation_operator

    return successor_installation_operator._execute()


def _arch134_d1s3_authority_check(repo_root: Path) -> tuple[str, ...]:
    failures = list(_arch134_d1s2_authority_check(repo_root))
    try:
        if (
            hashlib.sha256(
                json.dumps(ARCH134_D1S3_SHARED_SUCCESSOR_PINS, sort_keys=True).encode()
            ).hexdigest()
            != ARCH134_D1S3_SHARED_SUCCESSOR_PINS_SHA256
            or hashlib.sha256(
                json.dumps(ARCH134_D1S3_SOURCE_PINS, sort_keys=True).encode()
            ).hexdigest()
            != ARCH134_D1S3_SOURCE_PINS_SHA256
            or hashlib.sha256(
                json.dumps(ARCH134_D1S3_RUNNER_AST_PINS, sort_keys=True).encode()
            ).hexdigest()
            != ARCH134_D1S3_RUNNER_AST_PINS_SHA256
        ):
            failures.append("D1S3 overlay map digest drift")
        if set(ARCH134_D1S3_MUTABLE_CURRENT_DOCS) != {
            "docs/PROJECT_STATUS.md",
            "docs/AI_TRADING_BOT_HANDOFF.md",
        }:
            failures.append("D1S3 mutable current-doc set drift")
        if any(
            relative.startswith("docs/")
            and relative not in ARCH134_D1S3_MUTABLE_CURRENT_DOCS
            for relative in ARCH134_D1S3_MUTABLE_CURRENT_DOCS
        ):
            failures.append("D1S3 arbitrary document mutability")
        for relative, _pin in ARCH134_D1S3_SHARED_SUCCESSOR_PINS.items():
            if relative in ARCH134_D1S3_MUTABLE_CURRENT_DOCS:
                failures.append("D1S3 current-doc pin reintroduced: " + relative)
            elif not _authority_blob_matches(
                repo_root,
                repo_root / relative,
                _arch134_d1s3_shared_successor_pin(relative),
            ):
                failures.append("D1S3 shared successor drift: " + relative)
        for relative, pin in ARCH134_D1S3_SOURCE_PINS.items():
            if relative in ARCH134_D1S3_MUTABLE_CURRENT_DOCS:
                failures.append("D1S3 current-doc source pin reintroduced: " + relative)
            elif not _authority_blob_matches(repo_root, repo_root / relative, pin):
                failures.append("D1S3 source drift: " + relative)
        if (
            hashlib.sha256(
                json.dumps(ARCH134_D1S2_PREDECESSOR_PINS, sort_keys=True).encode()
            ).hexdigest()
            != ARCH134_D1S2_PREDECESSOR_PINS_SHA256
            or hashlib.sha256(
                json.dumps(ARCH134_D1S2_SUCCESSOR_PINS, sort_keys=True).encode()
            ).hexdigest()
            != ARCH134_D1S2_SUCCESSOR_PINS_SHA256
        ):
            failures.append("D1S2 accepted pin dictionaries changed")
        predecessor_probes = (
            (
                ARCH134_D1S2_PREDECESSOR_PINS,
                _arch134_d1s2_current_source_pin,
                "tests/runtime/checkpoint_runner/test_core.py",
            ),
            (
                ARCH134_D1S2_SOURCE_PREDECESSOR_PINS,
                _arch134_d1s2_source_pin,
                "tests/review_paper/test_arch134_f1r1_d1s1_successor_soak.py",
            ),
            (
                ARCH134_F1R1_C1_PREDECESSOR_SOURCE_PINS,
                _arch134_f1r1_c1_current_source_pin,
                "scripts/run_test_certification.py",
            ),
            (
                ARCH134_F1R1_C1_PREDECESSOR_TEST_PINS,
                _arch134_f1r1_c1_current_inventory_test_pin,
                "tests/runtime/checkpoint_runner/test_core.py",
            ),
            (
                ARCH134_F1R1_B_PREDECESSOR_SOURCE_PINS,
                _arch134_f1r1_b_current_source_pin,
                "scripts/run_test_certification.py",
            ),
            (
                ARCH134_F1R1_B_PREDECESSOR_TEST_PINS,
                _arch134_f1r1_b_current_inventory_test_pin,
                "tests/runtime/checkpoint_runner/test_core.py",
            ),
            (
                ARCH144C_PREDECESSOR_SOURCE_PINS,
                _arch144c_current_source_pin,
                "scripts/run_test_certification.py",
            ),
            (
                ARCH144C_PREDECESSOR_TEST_PINS,
                _arch144c_current_inventory_test_pin,
                "tests/runtime/checkpoint_runner/test_core.py",
            ),
            (
                ARCH145A_PREDECESSOR_SOURCE_PINS,
                _arch145a_current_source_pin,
                "scripts/run_test_certification.py",
            ),
            (
                ARCH145A_PREDECESSOR_TEST_PINS,
                _arch145a_current_inventory_test_pin,
                "tests/runtime/checkpoint_runner/test_core.py",
            ),
        )
        for pins, resolver, probe in predecessor_probes:
            if pins:
                for relative, predecessor in pins.items():
                    resolver(relative, predecessor)
            else:
                resolver(probe, "")
        tree = _authority_runner_tree(repo_root)
        functions = _top_level_functions(tree)
        for name, expected in ARCH134_D1S3_RUNNER_AST_PINS.items():
            expected = ARCH132_R3L_RUNNER_AST_PINS.get(
                name,
                ARCH132_R3K_RUNNER_AST_PINS.get(
                    name, ARCH132_R3J_RUNNER_AST_PINS.get(name, expected)
                ),
            )
            if name not in functions or not _authority_ast_matches(
                repo_root, name, functions[name], _arch134_r5_ast_pin(name, expected)
            ):
                failures.append("D1S3 runner AST drift: " + name)
        spec = _checkpoint_specs()[ARCH134_D1S3_NAME]
        if (
            spec.authority_check is not _arch134_d1s3_authority_check
            or spec.preflight is not _arch134_d1s3_preflight
            or spec.execute is not _arch134_d1s3_execute
            or spec.remote_branch != ARCH134_D1S3_BRANCH
            or spec.remote_head_env != ARCH134_D1S3_REMOTE_HEAD_ENV
            or spec.tests != ARCH134_D1S3_TESTS
            or spec.ruff_paths != ARCH134_D1S3_RUFF_PATHS
            or CI_CERTIFICATION_PROFILES.get(spec.name) != "robinhood"
            or not _batch_workflow_is_reviewed(
                (repo_root / ".github/workflows/checkpoint-source-gates.yml").read_text(
                    encoding="utf-8"
                )
            )
        ):
            failures.append("D1S3 registration drift")
    except (OSError, ValueError, TypeError, KeyError, SyntaxError):
        failures.append("D1S3 authority unavailable")
    return tuple(failures)


