def _arch134_readonly_diagnostic_predecessor_authority_check(
    repo_root: Path,
) -> tuple[str, ...]:
    """Compose historical reconstruction without current-drift exception lists."""
    return _readonly_predecessor_authority_check(repo_root)


def _arch134_readonly_diagnostic_graph_check(repo_root: Path) -> tuple[str, ...]:
    forbidden = {
        "rename",
        "replace",
        "move",
        "mkdir",
        "makedirs",
        "unlink",
        "rmdir",
        "SetSecurityInfo",
        "SetNamedSecurityInfoW",
        "SetFileInformationByHandle",
        "FileRenameInfo",
        "CreateDirectoryW",
        "WriteFile",
        "AdjustTokenPrivileges",
        "TerminateProcess",
        "CreateProcessW",
        "execute_once",
        "materialize_release",
        "consume_attempt",
        "eval",
        "exec",
        "compile",
    }
    failures = []
    for relative in (
        "src/trading_bot/supervised_release/deployment_admission_diagnostic.py",
        "src/trading_bot/supervised_release/deployment_admission_diagnostic_host.py",
    ):
        path = repo_root / relative
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except (OSError, SyntaxError):
            failures.append("Diagnostic successor source unavailable: " + relative)
            continue
        for node in ast.walk(tree):
            name = (
                node.id
                if isinstance(node, ast.Name)
                else node.attr
                if isinstance(node, ast.Attribute)
                else node.value
                if isinstance(node, ast.Constant) and isinstance(node.value, str)
                else ""
            )
            if name in forbidden or (
                isinstance(name, str) and name.startswith("MoveFile")
            ):
                failures.append("Diagnostic successor forbidden capability: " + name)
    return tuple(sorted(set(failures)))


def _arch134_readonly_diagnostic_authority_body(
    repo_root: Path,
) -> tuple[str, ...]:
    failures = list(_arch134_readonly_diagnostic_predecessor_authority_check(repo_root))
    try:
        _arch134_readonly_diagnostic_maps()
        specs = _readonly_checkpoint_specs()
        predecessor = specs[READONLY_ADMISSION_NAME]
        if (
            predecessor.preflight is not _readonly_admission_preflight
            or predecessor.execute is not None
            or predecessor.remote_branch != READONLY_ADMISSION_BRANCH
            or CI_CERTIFICATION_PROFILES.get(predecessor.name) != "robinhood"
        ):
            failures.append("Diagnostic predecessor registration drift")
        current = _checkpoint_specs()[ARCH134_READONLY_DIAGNOSTIC_NAME]
        if (
            current.preflight is not _arch134_readonly_diagnostic_preflight
            or current.execute is not None
            or current.remote_branch != ARCH134_READONLY_DIAGNOSTIC_BRANCH
            or current.tests != ARCH134_READONLY_DIAGNOSTIC_TESTS
            or current.ruff_paths != ARCH134_READONLY_DIAGNOSTIC_RUFF
            or CI_CERTIFICATION_PROFILES.get(current.name) != "robinhood"
            or _arch146a_overlay is not _arch134_readonly_diagnostic_overlay
            or _arch134_d1s3_shared_successor_pin
            is not _arch134_readonly_diagnostic_shared_successor_pin
            or resolve_ci_checkpoint(
                _checkpoint_specs(), ARCH134_READONLY_DIAGNOSTIC_BRANCH, "push"
            )
            != ARCH134_READONLY_DIAGNOSTIC_NAME
        ):
            failures.append("Diagnostic successor registration drift")
        workflow = (
            repo_root / ".github/workflows/checkpoint-source-gates.yml"
        ).read_text(encoding="utf-8")
        current_workflow = _arch134_current_batch_workflow_is_reviewed(workflow)
        if current_workflow:
            failures = [
                failure
                for failure in failures
                if failure != "R3N C4 workflow topology drift"
            ]
        else:
            failures.append("Diagnostic workflow topology drift")
        if (
            workflow.count(
                "              " + ARCH134_READONLY_DIAGNOSTIC_R1_NAME + " `\n"
            )
            != 1
            or workflow.count(
                "              arch134-fresh-successor-readonly-"
                "deployment-admission `\n"
            )
            != 0
        ):
            failures.append("Diagnostic active inventory drift")
        for relative, pin in ARCH134_READONLY_DIAGNOSTIC_BLOB_PINS.items():
            if not _authority_blob_matches(repo_root, repo_root / relative, pin):
                failures.append("Diagnostic successor source drift: " + relative)
        for relative, pin in ARCH134_READONLY_DIAGNOSTIC_SHARED_BLOB_PINS.items():
            if _arch134_readonly_diagnostic_shared_successor_pin(relative) != pin:
                failures.append("Diagnostic shared successor drift: " + relative)
        functions = _top_level_functions(_authority_runner_tree(repo_root))
        for name, pin in {
            **ARCH134_READONLY_DIAGNOSTIC_AST_PINS,
            **ARCH134_READONLY_DIAGNOSTIC_NEW_AST_PINS,
        }.items():
            if not _authority_ast_matches(repo_root, name, functions[name], pin):
                failures.append("Diagnostic successor runner AST drift: " + name)
        failures.extend(_arch134_readonly_diagnostic_graph_check(repo_root))
    except (OSError, KeyError, TypeError, ValueError, SyntaxError):
        failures.append("Diagnostic successor authority unavailable")
    return tuple(sorted(set(failures)))


def _arch134_readonly_diagnostic_authority_check(
    repo_root: Path,
) -> tuple[str, ...]:
    global _arch134_d1s3_shared_successor_pin, _arch146a_overlay
    previous_shared = _arch134_d1s3_shared_successor_pin
    previous_overlay = _arch146a_overlay
    _arch134_d1s3_shared_successor_pin = (
        _arch134_readonly_diagnostic_shared_successor_pin
    )
    _arch146a_overlay = _arch134_readonly_diagnostic_overlay
    try:
        return _arch134_readonly_diagnostic_authority_body(repo_root)
    finally:
        _arch134_d1s3_shared_successor_pin = previous_shared
        _arch146a_overlay = previous_overlay


def _arch134_r3n_prepublication_authority_check(repo_root: Path) -> tuple[str, ...]:
    """Require identity admission and both publication contexts before push."""
    failures = list(_arch132_r3n_admission_authority_check(repo_root))
    if failures:
        return tuple(failures)
    for result in _prepublication_authority_results(repo_root):
        failures.extend(
            result.context.value + ": " + failure for failure in result.failures
        )
    return tuple(failures)


def _prepublication_authority_results(repo_root: Path) -> tuple[AuthorityResult, ...]:
    results = tuple(
        evaluate_source_authority(repo_root, publication_context=context)
        for context in PublicationContext
    )
    for result in results:
        print(
            f"{result.context.value}_AUTHORITY={'PASS' if result.passed else 'FAIL'} "
            f"HEAD={result.head} TREE={result.tree} "
            f"CHECKPOINTS={len(result.checkpoints)}"
        )
    return results


