def execute_checkpoint(
    spec: CheckpointSpec,
    *,
    repo_root: Path,
    evidence_root: Path,
) -> tuple[bool, Path]:
    global _installation_execution_admitted, _installation_execution_source
    global _publication_execution_source
    if spec.execute is None:
        raise RuntimeError(f"checkpoint has no protected execution: {spec.name}")

    state_before = _git_state(repo_root)
    if state_before["porcelain"]:
        raise RuntimeError(
            f"protected execution requires a clean worktree; "
            f"found: {state_before['porcelain']}"
        )

    if spec.name == ARCH134_ACL_NAME:
        from trading_bot import shared_namespace_acl_recovery as recovery

        if spec != _checkpoint_specs()[ARCH134_ACL_NAME]:
            raise RuntimeError("R1 registration rejected")
        if os.environ.get(recovery.AUTH_ENV) != recovery.AUTH_VALUE:
            raise RuntimeError("R1 authorization interlock rejected")
        if re.fullmatch(r"[0-9a-f]{64}", os.environ.get(recovery.PLAN_ENV, "")) is None:
            raise RuntimeError("R1 reviewed-plan interlock rejected")

    if spec.name == ARCH134_D1S4_NAME:
        from trading_bot.supervised_release import (
            successor_direct_installation as direct,
        )

        if spec != _checkpoint_specs()[ARCH134_D1S4_NAME]:
            raise RuntimeError("D1S4 registration rejected")
        if os.environ.get(direct.AUTH_ENV) != direct.AUTH_VALUE:
            raise RuntimeError("D1S4 authorization interlock rejected")

    installation = spec.name == SUPERVISED_INSTALLATION_OPERATOR_NAME
    successor_installation = spec.name == ARCH134_D1S3_NAME
    if installation:
        from trading_bot.supervised_release import installation_operator as operator

        _supervised_installation_admission(repo_root, state_before)
        if spec != _checkpoint_specs()[SUPERVISED_INSTALLATION_OPERATOR_NAME]:
            raise RuntimeError("installation registration rejected")
        if os.environ.get(operator.AUTH_ENV) != operator.AUTH_VALUE:
            raise RuntimeError("installation authorization interlock rejected")
        if _supervised_installation_latch_consumed():
            raise RuntimeError(
                "PRESERVE_INSTALLATION_EVIDENCE_NO_RETRY: "
                "consumed installation attempt; MAY_HAVE_OCCURRED"
            )
    if successor_installation:
        from trading_bot.supervised_release import (
            successor_installation_operator as operator,
        )

        if spec != _checkpoint_specs()[ARCH134_D1S3_NAME]:
            raise RuntimeError("D1S3 installation registration rejected")
        if os.environ.get(operator.AUTH_ENV) != operator.AUTH_VALUE:
            raise RuntimeError("D1S3 installation authorization interlock rejected")
        attempt = operator.observe_attempt(operator.ATTEMPT_PATH)
        if attempt.state is not operator.AttemptState.AVAILABLE:
            raise RuntimeError(
                "PRESERVE_INSTALLATION_EVIDENCE_NO_RETRY: "
                "consumed or indeterminate D1S3 installation attempt"
            )

    local_branch = str(state_before["branch"])
    remote_branch = spec.remote_branch
    if remote_branch is None:
        if local_branch == "HEAD":
            raise RuntimeError(
                "detached protected execution requires a checkpoint-pinned "
                "remote branch"
            )
        remote_branch = local_branch

    remote_head = _remote_branch_head(repo_root, remote_branch)
    if remote_head != state_before["head"]:
        raise RuntimeError(
            "protected execution source is not the live remote branch head: "
            f"local={state_before['head']} "
            f"remote={remote_head} branch={remote_branch}"
        )

    evidence_dir = evidence_root / spec.name / f"execute-{_stamp()}"
    evidence_dir.mkdir(parents=True, exist_ok=False)
    attempt_path = evidence_dir / "attempt.json"
    _write_json(
        attempt_path,
        {
            "schema": SCHEMA,
            "kind": "protected_execution_attempt",
            "checkpoint": spec.name,
            "description": spec.description,
            "status": "STARTED",
            "source": {
                "before": state_before,
                "remote_branch": remote_branch,
                "remote_head": remote_head,
            },
            "automatic_retry": "NOT_AUTHORIZED",
        },
    )

    try:
        if installation:
            _installation_execution_admitted = True
            _installation_execution_source = (
                str(state_before["head"]),
                str(state_before["tree"]),
            )
        if spec.name == SUPERVISED_PUBLICATION_RECOVERY_NAME:
            _supervised_publication_admission(repo_root, state_before)
            if spec != _checkpoint_specs()[SUPERVISED_PUBLICATION_RECOVERY_NAME]:
                raise RuntimeError("publication recovery registration rejected")
            _publication_execution_source = (
                str(state_before["head"]),
                str(state_before["tree"]),
            )
        try:
            result = spec.execute()
        finally:
            _publication_execution_source = None
            if installation:
                _installation_execution_admitted = False
                _installation_execution_source = None
    except Exception as exc:
        state_after = _git_state(repo_root)
        identity_stable = (
            state_before["head"] == state_after["head"]
            and state_before["tree"] == state_after["tree"]
            and state_before["branch"] == state_after["branch"]
            and not state_after["porcelain"]
        )
        report = {
            "schema": SCHEMA,
            "kind": "protected_execution",
            "checkpoint": spec.name,
            "description": spec.description,
            "status": "STOPPED",
            "source": {
                "before": state_before,
                "after": state_after,
                "remote_branch": remote_branch,
                "remote_head": remote_head,
                "identity_stable": identity_stable,
            },
            "runner_error": {
                "type": "INSTALLATION_STOPPED" if installation else type(exc).__name__,
                "detail": "PRESERVE_INSTALLATION_EVIDENCE_NO_RETRY"
                if installation
                else str(exc),
            },
            "effect_disposition": "MAY_HAVE_OCCURRED",
            "protected_execution": "ATTEMPTED",
            "automatic_retry": "NOT_AUTHORIZED",
        }
        report_path = evidence_dir / "report.json"
        _write_json(report_path, report)
        if installation:
            print(
                "RUNNER_EXECUTION_ERROR=INSTALLATION_STOPPED:PRESERVE_INSTALLATION_EVIDENCE_NO_RETRY",
                file=sys.stderr,
            )
        else:
            print(f"RUNNER_EXECUTION_ERROR={type(exc).__name__}:{exc}", file=sys.stderr)
        print(f"IDENTITY_STABLE={identity_stable}")
        print(f"EVIDENCE={report_path}")
        print("OVERALL=STOPPED")
        return False, report_path

    state_after = _git_state(repo_root)
    identity_stable = (
        state_before["head"] == state_after["head"]
        and state_before["tree"] == state_after["tree"]
        and state_before["branch"] == state_after["branch"]
        and not state_after["porcelain"]
    )
    passed = result.get("status") == "PASS" and identity_stable
    if (
        spec.name
        in {
            SUPERVISED_PUBLICATION_RECOVERY_NAME,
            ARCH134_R5_NAME,
        }
        and not identity_stable
    ):
        result = {
            "status": "INDETERMINATE",
            "effect_disposition": "MAY_HAVE_OCCURRED",
            "automatic_retry": "NOT_AUTHORIZED",
            "primary": {
                "status": "INDETERMINATE",
                "reason": "RUNNER_SOURCE_DRIFT",
                "disposition": "PRESERVE_PUBLICATION_EVIDENCE_NO_RETRY",
            },
        }
    if spec.name in {ARCH134_D1S4_NAME, ARCH134_ACL_NAME} and not identity_stable:
        result = {
            **result,
            "status": "INDETERMINATE",
            "effect_disposition": "MAY_HAVE_OCCURRED",
            "automatic_retry": "NOT_AUTHORIZED",
            "primary": {
                **result.get("primary", {}),
                "status": "INDETERMINATE",
                "reason": "RUNNER_SOURCE_DRIFT",
                "disposition": (
                    "PRESERVE_SHARED_NAMESPACE_ACL_RECOVERY_EVIDENCE_NO_RETRY"
                )
                if spec.name == ARCH134_ACL_NAME
                else "PRESERVE_DIRECT_INSTALLATION_EVIDENCE_NO_RETRY",
                "execute_eligible": False,
            },
        }
    effect_disposition = result.get("effect_disposition", "MAY_HAVE_OCCURRED")

    report = {
        "schema": SCHEMA,
        "kind": "protected_execution",
        "checkpoint": spec.name,
        "description": spec.description,
        "status": "PASS" if passed else "STOPPED",
        "source": {
            "before": state_before,
            "after": state_after,
            "remote_branch": remote_branch,
            "remote_head": remote_head,
            "identity_stable": identity_stable,
        },
        "result": result,
        "effect_disposition": effect_disposition,
        "protected_execution": "ATTEMPTED",
        "automatic_retry": "NOT_AUTHORIZED",
    }
    report_path = evidence_dir / "report.json"
    _write_json(report_path, report)

    primary = result.get("primary")
    if isinstance(primary, dict):
        print(f"PRIMARY_STATUS={primary.get('status')}")
        if primary.get("reason") is not None:
            print(f"PRIMARY_REASON={primary.get('reason')}")
        if primary.get("detail") is not None:
            print(f"PRIMARY_DETAIL={primary.get('detail')}")
    print(f"EFFECT_DISPOSITION={effect_disposition}")
    print(f"IDENTITY_STABLE={identity_stable}")
    print(f"EVIDENCE={report_path}")
    print(f"OVERALL={'PASS' if passed else 'STOPPED'}")
    return passed, report_path


def _status(repo_root: Path, specs: Mapping[str, CheckpointSpec]) -> int:
    state = _git_state(repo_root)
    print(f"SCHEMA={SCHEMA}")
    print(f"REPO={repo_root}")
    print(f"HEAD={state['head']}")
    print(f"TREE={state['tree']}")
    print(f"BRANCH={state['branch']}")
    print(f"CLEAN={not bool(state['porcelain'])}")
    print("READ_ONLY_PREFLIGHT=IMPLEMENTED_FOR_REGISTERED_PROFILES")
    execute_specs = sorted(
        name for name, spec in specs.items() if spec.execute is not None
    )
    print(
        "PROTECTED_EXECUTION="
        + (
            "IMPLEMENTED_FOR_" + ",".join(execute_specs)
            if execute_specs
            else "NOT_IMPLEMENTED"
        )
    )
    print("CHECKPOINTS=" + ",".join(sorted(specs)))
    for name in sorted(specs):
        print(f"{name}: {specs[name].description}")
    return 0


def _parser(specs: Mapping[str, CheckpointSpec]) -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    subparsers = parser.add_subparsers(dest="command", required=True)

    subparsers.add_parser("status", help="show runner and repository status")

    verify = subparsers.add_parser(
        "verify",
        help="run a source-only checkpoint gate",
    )
    verify.add_argument("checkpoint", choices=sorted(specs))
    verify.add_argument(
        "--evidence-root",
        type=Path,
        help="override the external checkpoint evidence root",
    )

    batch = subparsers.add_parser("verify-batch", help="share registered source gates")
    batch.add_argument("checkpoints", nargs="+", choices=sorted(specs))
    batch.add_argument("--evidence-root", type=Path)
    for command in ("classify-ci", "verify-docs"):
        changes = subparsers.add_parser(command, help="source-only CI change gate")
        changes.add_argument("--evidence-root", type=Path)

    admission = subparsers.add_parser(
        "admit",
        help="run the Architecture 132-R3N pre-publication admission gate",
    )
    admission.add_argument("--evidence-root", type=Path)

    preflight_specs = sorted(
        name for name, spec in specs.items() if spec.preflight is not None
    )
    preflight = subparsers.add_parser(
        "preflight",
        help="run a registered read-only host preflight",
    )
    preflight.add_argument("checkpoint", choices=preflight_specs)
    preflight.add_argument(
        "--evidence-root",
        type=Path,
        help="override the external checkpoint evidence root",
    )

    execute_specs = sorted(
        name for name, spec in specs.items() if spec.execute is not None
    )
    execute = subparsers.add_parser(
        "execute",
        help="run a registered protected checkpoint after explicit authorization",
    )
    execute.add_argument("checkpoint", choices=execute_specs)
    execute.add_argument(
        "--evidence-root",
        type=Path,
        help="override the external checkpoint evidence root",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    repo_root = Path(__file__).resolve().parent.parent
    specs = _checkpoint_specs()
    parser = _parser(specs)
    args = parser.parse_args(argv)
    if args.command == "verify-batch" and len(set(args.checkpoints)) != len(
        args.checkpoints
    ):
        parser.error("duplicate checkpoint names are not allowed")

    if args.command == "status":
        return _status(repo_root, specs)

    evidence_root = (
        args.evidence_root
        if args.evidence_root is not None
        else _default_evidence_root(repo_root)
    )

    try:
        if args.command == "verify-batch":
            passed, _ = verify_batch(
                [specs[name] for name in args.checkpoints],
                repo_root=repo_root,
                evidence_root=evidence_root,
            )
            return 0 if passed else 1
        if args.command in {"classify-ci", "verify-docs"}:
            passed, _ = verify_ci_changes(
                repo_root=repo_root,
                evidence_root=evidence_root,
                docs_only=args.command == "verify-docs",
            )
            return 0 if passed else 1
        if args.command == "admit":
            passed, _ = prepublication_admission(
                repo_root=repo_root,
                evidence_root=evidence_root,
            )
            return 0 if passed else 1
        spec = specs[args.checkpoint]
        if args.command == "verify":
            passed, _ = verify_checkpoint(
                spec,
                repo_root=repo_root,
                evidence_root=evidence_root,
            )
        elif args.command == "preflight":
            passed, _ = preflight_checkpoint(
                spec,
                repo_root=repo_root,
                evidence_root=evidence_root,
            )
        else:
            passed, _ = execute_checkpoint(
                spec,
                repo_root=repo_root,
                evidence_root=evidence_root,
            )
    except Exception as exc:
        if getattr(
            args, "checkpoint", None
        ) == SUPERVISED_INSTALLATION_OPERATOR_NAME and args.command in {
            "preflight",
            "execute",
        }:
            print(
                "RUNNER_ERROR=INSTALLATION_AUTHORITY_REJECTED_OR_CONSUMED:NO_RETRY",
                file=sys.stderr,
            )
        else:
            print(f"RUNNER_ERROR={type(exc).__name__}:{exc}", file=sys.stderr)
        return 2

    return 0 if passed else 1


def _arch147_authority_check(repo_root: Path) -> tuple[str, ...]:
    """Own the current ordinary desktop research profile and source route."""
    from scripts.arch147_source_authority import desktop_export_authority_failures

    failures = list(desktop_export_authority_failures(repo_root))
    specs = _checkpoint_specs()
    spec = specs.get(ARCH147_NAME)
    if (
        spec is None
        or spec.tests != ARCH147_TESTS
        or spec.ruff_paths != ARCH147_RUFF
        or spec.remote_branch != ARCH147_BRANCH
        or spec.preflight is not None
        or spec.execute is not None
        or spec.remote_head_env is not None
        or CI_CERTIFICATION_PROFILES.get(ARCH147_NAME) != "full"
        or CURRENT_ACTIVE_CI_CHECKPOINTS.count(ARCH147_NAME) != 1
        or resolve_ci_checkpoint(specs, ARCH147_BRANCH, "push") != ARCH147_NAME
    ):
        failures.append("147 desktop source-only registration drift")
    if any(
        name in CURRENT_ACTIVE_CI_CHECKPOINTS
        for name in (ARCH146_PARTIAL_STATE_NAME, ARCH146_PRE_B2_NAME, ARCH146B1_NAME)
    ):
        failures.append("147 consumed Architecture 146 route remains current")
    workflow = (repo_root / ".github/workflows/checkpoint-source-gates.yml").read_text(
        encoding="utf-8"
    )
    if workflow.count("              " + ARCH147_NAME + " `\n") != 1:
        failures.append("147 active CI membership drift")
    if any(
        "              " + name + " `\n" in workflow
        for name in (ARCH146_PARTIAL_STATE_NAME, ARCH146_PRE_B2_NAME, ARCH146B1_NAME)
    ):
        failures.append("147 historical Architecture 146 workflow route remains active")
    desktop_path = repo_root / (
        "src/trading_bot/experiments/historical_research_desktop.py"
    )
    desktop_source = desktop_path.read_text(encoding="utf-8")
    desktop_tree = ast.parse(desktop_source, filename=str(desktop_path))
    open_loader = next(
        node
        for node in ast.walk(desktop_tree)
        if isinstance(node, ast.FunctionDef)
        and node.name == "load_desktop_open_research"
    )
    if "ACCEPTED_CUSTODY_ADMISSIONS" in desktop_source or (
        "load_desktop_final_holdout"
        in (ast.get_source_segment(desktop_source, open_loader) or "")
    ):
        failures.append("147 OPEN loader crosses the final-holdout boundary")
    if "ResearchStrategyFinalHoldoutAdmission" not in desktop_source:
        failures.append("147 final loader admission binding missing")
    if (
        'DESKTOP_RESEARCH_ROOT = Path(r"F:\\AI\\ai-trading-bot\\data\\research\\'
        'desktop-v1")' not in desktop_source
    ):
        failures.append("147 fixed desktop root drift")
    for relative in (
        "src/trading_bot/experiments/desktop_research_dataset.py",
        "src/trading_bot/experiments/historical_research_desktop.py",
        "src/trading_bot/experiments/desktop_research_campaign.py",
        "src/trading_bot/portfolio/optimizer.py",
        "src/trading_bot/experiments/research_candidate.py",
        "src/trading_bot/experiments/research_candidate_walk_forward.py",
        "src/trading_bot/experiments/research_strategy_walk_forward.py",
    ):
        candidate_path = repo_root / relative
        candidate = candidate_path.read_text(encoding="utf-8")
        if relative.startswith("src/trading_bot/experiments/"):
            candidate_tree = ast.parse(candidate, filename=str(candidate_path))
            imported = {
                node.module or ""
                for node in ast.walk(candidate_tree)
                if isinstance(node, ast.ImportFrom)
            } | {
                alias.name
                for node in ast.walk(candidate_tree)
                if isinstance(node, ast.Import)
                for alias in node.names
            }
            if any(
                module.startswith(("ctypes", "win32", "winreg", "robinhood", "alpaca"))
                for module in imported
            ):
                failures.append("147 desktop path has forbidden host/provider import")
            if "ACCEPTED_CUSTODY_ADMISSIONS" in candidate:
                failures.append("147 desktop path depends on custody admission")
        if (
            relative != "src/trading_bot/experiments/historical_research_desktop.py"
            and "load_desktop_final_holdout" in candidate
        ):
            failures.append("147 optimizer-facing holdout import: " + relative)
    return tuple(failures)


def _arch147_p4_authority_check(repo_root: Path) -> tuple[str, ...]:
    """Own P4 registration and the offline supervisor's narrow import boundary."""
    specs = _checkpoint_specs()
    spec = specs.get(ARCH147_P4_NAME)
    failures = []
    if (
        spec is None
        or spec.tests != ARCH147_P4_TESTS
        or spec.ruff_paths != ARCH147_P4_RUFF
        or spec.authority_check is not _arch147_p4_authority_check
        or spec.remote_branch != ARCH147_P4_BRANCH
        or spec.preflight is not None
        or spec.execute is not None
        or spec.remote_head_env is not None
        or CI_CERTIFICATION_PROFILES.get(ARCH147_P4_NAME) != "full"
        or CURRENT_ACTIVE_CI_CHECKPOINTS.count(ARCH147_P4_NAME) != 1
        or CURRENT_ACTIVE_CI_CHECKPOINTS[0] != ARCH147_P4_NAME
        or resolve_ci_checkpoint(specs, ARCH147_P4_BRANCH, "push") != ARCH147_P4_NAME
    ):
        failures.append("147 P4 desktop supervisor source-only registration drift")
    if (
        ARCH147_NAME not in CURRENT_ACTIVE_CI_CHECKPOINTS
        or CI_CERTIFICATION_PROFILES.get(ARCH147_NAME) != "full"
        or resolve_ci_checkpoint(specs, ARCH147_BRANCH, "push") != ARCH147_NAME
    ):
        failures.append("147 P3 desktop research route was not preserved")
    if any(
        name in CURRENT_ACTIVE_CI_CHECKPOINTS
        for name in (ARCH146_PARTIAL_STATE_NAME, ARCH146_PRE_B2_NAME, ARCH146B1_NAME)
    ):
        failures.append("147 P4 consumed Architecture 146 route remains current")

    workflow = (repo_root / ".github/workflows/checkpoint-source-gates.yml").read_text(
        encoding="utf-8"
    )
    for name in (ARCH147_P4_NAME, ARCH147_NAME):
        if workflow.count("              " + name + " `\n") != 1:
            failures.append("147 P4 active CI membership drift: " + name)

    def import_claims(relative: str) -> tuple[tuple[str, str], ...]:
        tree = ast.parse((repo_root / relative).read_text(encoding="utf-8"))
        claims = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                claims.extend((alias.name, "*") for alias in node.names)
            elif isinstance(node, ast.ImportFrom):
                module = "." * node.level + (node.module or "")
                claims.extend((module, alias.name) for alias in node.names)
        return tuple(sorted(claims))

    expected_imports = {
        "src/trading_bot/desktop_runtime.py": (
            ("__future__", "annotations"),
            ("json", "*"),
            ("os", "*"),
            ("collections.abc", "Callable"),
            ("dataclasses", "dataclass"),
            ("datetime", "UTC"),
            ("datetime", "datetime"),
            ("enum", "StrEnum"),
            ("pathlib", "Path"),
            ("queue", "Empty"),
            ("queue", "Full"),
            ("queue", "Queue"),
            ("threading", "Event"),
            ("threading", "Lock"),
            ("threading", "Thread"),
            ("threading", "current_thread"),
            ("typing", "Protocol"),
            ("uuid", "UUID"),
            ("hashlib", "sha256"),
            (
                "trading_bot.experiments.desktop_research_campaign",
                "read_desktop_campaign_bundle",
            ),
        ),
        "src/trading_bot/gui/desktop_control.py": (
            ("PySide6.QtCore", "QTimer"),
            ("PySide6.QtWidgets", "QHBoxLayout"),
            ("PySide6.QtWidgets", "QLabel"),
            ("PySide6.QtWidgets", "QPushButton"),
            ("PySide6.QtWidgets", "QVBoxLayout"),
            ("PySide6.QtWidgets", "QWidget"),
            ("trading_bot.desktop_runtime", "DesktopSupervisor"),
        ),
        "scripts/run_desktop_bot.py": (
            ("__future__", "annotations"),
            ("argparse", "*"),
            ("sys", "*"),
            ("pathlib", "Path"),
            ("trading_bot.desktop_runtime", "ArtifactIdentity"),
            ("trading_bot.desktop_runtime", "DesktopSupervisor"),
            ("trading_bot.desktop_runtime", "InspectBundle"),
            ("trading_bot.desktop_runtime", "LifecycleJournal"),
            ("trading_bot.desktop_runtime", "LocalResearchWorker"),
            ("PySide6.QtWidgets", "QApplication"),
            ("trading_bot.gui.main_window", "MainWindow"),
            ("trading_bot.gui.desktop_service", "DesktopGuiService"),
        ),
        "src/trading_bot/gui/desktop_service.py": (
            ("pathlib", "Path"),
            (
                "trading_bot.gui.desktop_campaign_service",
                "DesktopCampaignResearchService",
            ),
            ("trading_bot.gui.market_data_models", "MarketDataPageState"),
            ("trading_bot.gui.market_data_models", "unavailable_market_data_state"),
            ("trading_bot.gui.models", "ApplicationOverview"),
            ("trading_bot.gui.models", "ComponentStatus"),
            ("trading_bot.gui.models", "OperatingMode"),
            ("trading_bot.gui.models", "PresentationStatus"),
            ("trading_bot.gui.models", "ResearchPageState"),
            (
                "trading_bot.gui.operator_observability_models",
                "OperatorOperationsPageState",
            ),
            (
                "trading_bot.gui.operator_observability_models",
                "unavailable_operator_operations_state",
            ),
            ("trading_bot.gui.paper_account_models", "PaperAccountPageState"),
            (
                "trading_bot.gui.paper_account_models",
                "unavailable_paper_account_state",
            ),
            ("trading_bot.gui.paper_models", "PaperPageState"),
            ("trading_bot.gui.paper_models", "unavailable_paper_state"),
            (
                "trading_bot.gui.production_strategy_models",
                "ProductionStrategyPageState",
            ),
            (
                "trading_bot.gui.production_strategy_models",
                "unavailable_production_strategy_state",
            ),
            (
                "trading_bot.gui.research_candidate_lifecycle_models",
                "ResearchCandidateLifecyclePageState",
            ),
            (
                "trading_bot.gui.research_candidate_lifecycle_models",
                "unavailable_research_candidate_lifecycle_state",
            ),
            ("trading_bot.gui.research_service", "unavailable_research_state"),
            ("trading_bot.gui.runtime_models", "RuntimePageState"),
            ("trading_bot.gui.runtime_models", "unavailable_runtime_state"),
        ),
    }
    for relative, expected in expected_imports.items():
        if import_claims(relative) != tuple(sorted(expected)):
            failures.append("147 P4 effect import boundary drift: " + relative)

    main_window_claims = import_claims("src/trading_bot/gui/main_window.py")
    if (
        main_window_claims.count(("trading_bot.desktop_runtime", "DesktopSupervisor"))
        != 1
        or main_window_claims.count(
            ("trading_bot.gui.desktop_control", "DesktopControl")
        )
        != 1
    ):
        failures.append("147 P4 optional GUI controller imports drift")

    def module_import_claims(relative: str) -> tuple[tuple[str, str], ...]:
        tree = ast.parse((repo_root / relative).read_text(encoding="utf-8"))
        claims = []
        for node in tree.body:
            if isinstance(node, ast.Import):
                claims.extend((alias.name, "*") for alias in node.names)
            elif isinstance(node, ast.ImportFrom):
                module = "." * node.level + (node.module or "")
                claims.extend((module, alias.name) for alias in node.names)
        return tuple(sorted(claims))

    gui_package_imports = module_import_claims("src/trading_bot/gui/__init__.py")
    deferred_gui_modules = (
        "trading_bot.gui.startup_composition",
        "trading_bot.gui.paper_inspection_service",
        "trading_bot.gui.verified_genesis_paper_account_inspection_service",
        "trading_bot.gui.verified_snapshot_inspection_service",
        "trading_bot.gui.verified_successor_paper_account_inspection_service",
    )
    if any(module in deferred_gui_modules for module, _ in gui_package_imports):
        failures.append("147 P4 GUI package eagerly imports deferred adapters")
    if (
        "trading_bot.cli.historical_experiment_report_serialization",
        "deserialize_compact_report_json",
    ) in module_import_claims("src/trading_bot/gui/research_service.py"):
        failures.append("147 P4 compact legacy parser import is not deferred")

    forbidden_modules = (
        "alpaca",
        "robinhood",
        "win32",
        "winreg",
        "ctypes",
        "requests",
        "httpx",
        "websocket",
    )
    forbidden_project_prefixes = (
        "trading_bot.alpaca",
        "trading_bot.robinhood",
        "trading_bot.execution",
        "trading_bot.risk",
        "trading_bot.broker",
        "trading_bot.live",
        "trading_bot.supervised_release",
    )
    reviewed_sources = (
        "src/trading_bot/desktop_runtime.py",
        "src/trading_bot/gui/desktop_control.py",
        "src/trading_bot/gui/main_window.py",
        "src/trading_bot/gui/__init__.py",
        "src/trading_bot/gui/research_service.py",
        "src/trading_bot/gui/desktop_service.py",
        "scripts/run_desktop_bot.py",
    )
    forbidden_source_tokens = (
        "load_desktop_final_holdout",
        "ResearchStrategyFinalHoldoutAdmission",
        "ACCEPTED_CUSTODY_ADMISSIONS",
        "historical_research_desktop",
    )
    for relative in reviewed_sources:
        source = (repo_root / relative).read_text(encoding="utf-8")
        claims = import_claims(relative)
        forbidden_import = False
        for module, name in claims:
            if module.split(".", 1)[0] in forbidden_modules:
                forbidden_import = True
            if module.startswith(forbidden_project_prefixes):
                if not (
                    relative == "src/trading_bot/gui/research_service.py"
                    and module == "trading_bot.execution.state_fingerprints"
                    and name == "canonical_decimal"
                ):
                    forbidden_import = True
        if forbidden_import:
            failures.append("147 P4 forbidden effect import: " + relative)
        if any(token in source for token in forbidden_source_tokens):
            failures.append("147 P4 forbidden holdout path: " + relative)
    return tuple(failures)


def _arch146b1_authority_check(repo_root: Path) -> tuple[str, ...]:
    """Current semantic owner; no historical source pins or native dispatch."""
    failures = []
    spec = _checkpoint_specs().get(ARCH146B1_NAME)
    if (
        spec is None
        or spec.tests != ARCH146B1_TESTS
        or spec.ruff_paths != ARCH146B1_RUFF
        or spec.remote_branch != ARCH146B1_BRANCH
        or spec.preflight is not None
        or spec.execute is not None
        or CI_CERTIFICATION_PROFILES.get(ARCH146B1_NAME) != "full"
        or CURRENT_ACTIVE_CI_CHECKPOINTS.count(ARCH146B1_NAME) != 1
        or resolve_ci_checkpoint(_checkpoint_specs(), ARCH146B1_BRANCH, "push")
        != ARCH146B1_NAME
    ):
        failures.append("146-B1 source-only registration drift")
    forbidden = {
        "open",
        "exec",
        "eval",
        "compile",
        "rename",
        "replace",
        "unlink",
        "mkdir",
        "makedirs",
        "read_text",
        "write_text",
        "read_bytes",
        "write_bytes",
    }
    for relative in ARCH146B1_RUFF[:2]:
        tree = ast.parse((repo_root / relative).read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                name = (
                    node.func.id
                    if isinstance(node.func, ast.Name)
                    else node.func.attr
                    if isinstance(node.func, ast.Attribute)
                    else ""
                )
                # String.replace is canonical timestamp formatting, not a
                # namespace effect. No native/filesystem imports are allowed.
                if name in forbidden - {"replace"} and not (
                    isinstance(node.func, ast.Attribute)
                    and isinstance(node.func.value, ast.Name)
                    and node.func.value.id == "re"
                    and name == "compile"
                ):
                    failures.append("146-B1 forbidden direct effect: " + name)
            names = (
                [item.name for item in node.names]
                if isinstance(node, ast.Import)
                else [node.module or ""]
                if isinstance(node, ast.ImportFrom)
                else []
            )
            if any(
                name.startswith(
                    (
                        "http",
                        "socket",
                        "ctypes",
                        "subprocess",
                        "os",
                        "pathlib",
                        "winreg",
                        "trading_bot.runtime",
                        "trading_bot.review_paper",
                        "trading_bot.supervised_release",
                    )
                )
                for name in names
            ):
                failures.append("146-B1 forbidden effect import")
        for node in tree.body:
            if (
                isinstance(node, ast.AnnAssign)
                and isinstance(node.target, ast.Name)
                and node.target.id
                in {
                    "ACCEPTED_CUSTODY_ADMISSIONS",
                }
            ):
                if not isinstance(node.value, ast.Tuple) or node.value.elts:
                    failures.append(
                        "146-B1 cannot self-admit real custody/calendar authority"
                    )
    return tuple(failures)


def _arch146_pre_b2_authority_check(repo_root: Path) -> tuple[str, ...]:
    """Current owner of accepted published authority and the native B2 boundary."""
    failures = []
    spec = _checkpoint_specs().get(ARCH146_PRE_B2_NAME)
    if (
        spec is None
        or spec.tests != ARCH146_PRE_B2_TESTS
        or spec.ruff_paths != ARCH146_PRE_B2_RUFF
        or spec.remote_branch != ARCH146_PRE_B2_BRANCH
        or spec.preflight is not None
        or spec.execute is not None
        or CI_CERTIFICATION_PROFILES.get(ARCH146_PRE_B2_NAME) != "full"
        or CURRENT_ACTIVE_CI_CHECKPOINTS.count(ARCH146_PRE_B2_NAME) != 1
        or resolve_ci_checkpoint(_checkpoint_specs(), ARCH146_PRE_B2_BRANCH, "push")
        != ARCH146_PRE_B2_NAME
    ):
        failures.append("146 pre-B2 source registration drift")
    try:
        from scripts.arch146_source_authority import (
            research_credential_boundary_isolated,
            research_custody_ace_semantics_current,
            research_source_binding_tracked_only_current,
        )
        from trading_bot.experiments import historical_research_custody as custody
        from trading_bot.experiments.historical_research_native import (
            credential_binding_is_current,
        )
        from trading_bot.experiments.historical_research_sessions import (
            AUTHORITY_DIGEST,
            SOURCE_MANIFEST_SHA256,
            published_historical_session_authority,
            reconcile_historical_session_model,
        )

        if (
            not credential_binding_is_current()
            or not research_credential_boundary_isolated(repo_root)
        ):
            failures.append("146 B2 ephemeral research credential policy drift")
        if not research_custody_ace_semantics_current(repo_root):
            failures.append("146 custody exact allow ACE multiset policy drift")
        if not research_source_binding_tracked_only_current(repo_root):
            failures.append("146 tracked-only source-binding policy drift")
        authority = published_historical_session_authority()
        if custody.ACCEPTED_CUSTODY_ADMISSIONS or (
            custody.ACCEPTED_HISTORICAL_SESSION_AUTHORITIES != (authority,)
            or authority.digest != AUTHORITY_DIGEST
        ):
            failures.append("146 accepted authority/admission drift")
        reconcile_historical_session_model(authority)
        manifest = (
            repo_root
            / "docs/validation/evidence/arch146/historical-session-source-manifest.json"
        )
        if hashlib.sha256(manifest.read_bytes()).hexdigest() != SOURCE_MANIFEST_SHA256:
            failures.append("146 source manifest byte drift")
        for relative in (
            "src/trading_bot/experiments/historical_research_native_custody.py",
            "src/trading_bot/experiments/historical_research_b2_preflight.py",
        ):
            tree = ast.parse((repo_root / relative).read_text(encoding="utf-8"))
            for node in ast.walk(tree):
                if (
                    isinstance(node, ast.Attribute)
                    and node.attr
                    in {
                        "rename",
                        "replace",
                        "unlink",
                        "rmdir",
                        "rmtree",
                        "MoveFileW",
                        "MoveFileExW",
                        "SetFileInformationByHandle",
                    }
                    and node.attr != "replace"
                ):
                    failures.append("146 forbidden publication/cleanup primitive")
    except (OSError, ValueError, TypeError, KeyError):
        failures.append("146 published authority unavailable")
    return tuple(failures)


def _arch146_partial_state_preflight() -> dict[str, object]:
    from trading_bot.experiments.historical_research_partial_state import (
        partial_state_readonly_preflight,
    )

    return partial_state_readonly_preflight()


def _arch146_partial_state_authority_check(repo_root: Path) -> tuple[str, ...]:
    """Current semantic owner of the additive read-only observer registration."""
    from scripts.arch146_source_authority import partial_state_observer_is_readonly

    failures = []
    specs = _checkpoint_specs()
    spec = specs.get(ARCH146_PARTIAL_STATE_NAME)
    if (
        spec is None
        or sum(value.name == ARCH146_PARTIAL_STATE_NAME for value in specs.values())
        != 1
        or spec.tests != ARCH146_PARTIAL_STATE_TESTS
        or spec.ruff_paths != ARCH146_PARTIAL_STATE_RUFF
        or spec.remote_branch != ARCH146_PARTIAL_STATE_BRANCH
        or spec.preflight is not _arch146_partial_state_preflight
        or spec.execute is not None
        or spec.remote_head_env is not None
        or CI_CERTIFICATION_PROFILES.get(ARCH146_PARTIAL_STATE_NAME) != "full"
        or CURRENT_ACTIVE_CI_CHECKPOINTS.count(ARCH146_PARTIAL_STATE_NAME) != 1
        or resolve_ci_checkpoint(specs, ARCH146_PARTIAL_STATE_BRANCH, "push")
        != ARCH146_PARTIAL_STATE_NAME
    ):
        failures.append("146 partial-state read-only registration drift")
    workflow = (repo_root / ".github/workflows/checkpoint-source-gates.yml").read_text(
        encoding="utf-8"
    )
    if workflow.count("              " + ARCH146_PARTIAL_STATE_NAME + " `\n") != 1:
        failures.append("146 partial-state active CI membership drift")
    if not partial_state_observer_is_readonly(repo_root):
        failures.append("146 partial-state read-only composition drift")
    return tuple(failures)


def _arch146_partial_state_preflight_checkpoint(
    spec: CheckpointSpec, *, repo_root: Path, evidence_root: Path
) -> tuple[bool, Path | None]:
    if spec.name != ARCH146_PARTIAL_STATE_NAME:
        return _arch134_readonly_diagnostic_r3_preflight_checkpoint(
            spec, repo_root=repo_root, evidence_root=evidence_root
        )
    if spec != _checkpoint_specs()[
        ARCH146_PARTIAL_STATE_NAME
    ] or _arch146_partial_state_authority_check(repo_root):
        raise RuntimeError("Partial-state observer source/registration rejected")
    return _PRE_READONLY_PREFLIGHT(
        spec, repo_root=repo_root, evidence_root=evidence_root
    )


preflight_checkpoint = _arch146_partial_state_preflight_checkpoint


_PRE_DISTRIBUTED_FIND_REUSABLE = find_reusable_ci_certification


def _distributed_find_reusable_ci_certification(specs, **kwargs):
    from scripts.distributed_full import find_reusable

    return find_reusable(_PRE_DISTRIBUTED_FIND_REUSABLE, specs, **kwargs)


find_reusable_ci_certification = _distributed_find_reusable_ci_certification


